    info "ê¸°ì¡´ ì„¤ì¹˜ë¥¼ ì—…ê·¸ë ˆì´ë“œí•©ë‹ˆë‹¤: $PREFIX ($(cat "$PREFIX/VERSION" 2>/dev/null || echo 'ë²„ì „ ì •ë³´ ì—†ìŒ'))"
  fi
