  # ê¸°ë™ í™•ì¸ (ìµœëŒ€ 15ì´ˆ)
  local ok=0 i
  for i in $(seq 1 15); do
    if "$PY" - "$PORT" <<'EOF' 2>/dev/null
import sys, urllib.request
opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
opener.open("http://127.0.0.1:%s/api/agents" % sys.argv[1], timeout=2).read()
EOF
